script:
class Component extends DCLogic {
  constructor(props) { super(props); this.state = { tab: 'con', sec: 0, rOpen: {}, m: '', signed: false, step: 1, agree: false, agreeErr: false, code: '', codeErr: false, rev: '',
    st: { c1: 'given', c2: 'given', p1: 'given', p2: 'revoked', p3: 'none', p4: 'given' } }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  renderVals() {
    const S = this.state;
    const T = [['con', 'Согласия'], ['reg', 'Регламент'], ['rul', 'Правила программы']];
    const tabs = T.map(([k, t]) => ({ t, sel: S.tab === k, pick: () => this.setState({ tab: k, toast: '' }) }));
    const setSt = (id, v) => this.setState({ st: Object.assign({}, S.st, { [id]: v }), m: '' });
    const LAB = { given: ['Дано', 'badge--ok'], revoked: ['Отозвано', 'badge--muted'], none: ['Не дано', 'badge--muted'] };
    const row = (id, name, sub, ask, noAct) => ({ name, sub, state: LAB[S.st[id]][0], badge: LAB[S.st[id]][1], hasAct: !noAct,
      actLabel: S.st[id] === 'given' ? 'Отозвать' : 'Дать согласие',
      act: (e) => { if (S.st[id] === 'given') { if (ask) this.openM('rev', e, { rev: id }); else { setSt(id, 'revoked'); this.say('Согласие отозвано', e); } } else { setSt(id, 'given'); this.say('Согласие дано', e); } } });
    const cons = HB.isNovice() ? [] : [row('c1', 'Андрей Крылов', 'Согласие на связь от Housebook', true), row('c2', 'Дмитрий Орлов', 'Согласие на связь от Housebook', true)];
    const mine = [row('p1', 'Проверка личности, включая проверку по лицу', 'Без согласия мы не можем проверить Вас: передачи клиентов и выплаты ждут, причина видна в кабинете.', true),
      row('p2', 'Передача моих данных за пределы ОАЭ', '', false), row('p3', 'Новости и предложения по желанию', 'Это не обязательно.', false),
      Object.assign(row('p4', 'Подтверждение, что Вас проинформировали', 'Это подтверждение, а не согласие.', false, true), {})];
    const SEC = [
      { t: '1. Кого приводить', p: ['Приводите человека, который задумался о покупке за рубежом и с которым Вы уже поговорили лично. Нужен живой интерес, а не список контактов.', 'Не стоит приводить:'], l: ['человека, чей бюджет не подходит под проекты застройщика', 'того, кто ищет объект в другой стране или городе, чем открытые на платформе', 'того, кто прямо сказал, что пока не готов покупать', 'того, у кого уже есть агент или локальный партнёр по этой покупке'], },
      { t: '2. Как принимается заявка', p: ['Платформа сначала проверяет, что это не спам. Подозрительные заявки идут в ручной разбор, а не отклоняются сами.', 'Если этот человек уже есть в системе, вторая заявка не создаётся: заявки объединяются или, если данные расходятся, открывается спор и обе претензии замораживаются до решения.', 'Без согласия клиента на связь заявка сохраняется, но писать ему нельзя, пока согласие не появится. Если интереса пока мало, заявка уходит в фоновый прогрев. Отказ всегда приходит с причиной.'], l: [] },
      { t: '3. Готовность клиента и Ваша доля', p: ['В момент передачи платформа оценивает готовность клиента. От балла зависит Ваша доля от всей комиссии застройщика.', 'Окончательное деление фиксируется при закрытии заявки. Оно остаётся исходным или сдвигается в пользу локального партнёра, но только по записям платформы о поведении клиента, а не за время работы партнёра. Все изменения видны в карточке заявки на странице «Почему столько». Прошлые заявки задним числом не пересчитываются.'], l: ['балл от 70: Ваша доля 40%', 'балл от 41 до 69: 35%', 'балл 40 и ниже: 30%'] },
      { t: '4. Что происходит после передачи', p: ['Заявку получает локальный партнёр в стране объекта. Рабочее окно: с 9 утра до 9 вечера по времени столицы страны, семь дней в неделю. В нём идёт обратный отсчёт: сначала взять заявку в работу, затем впервые связаться с клиентом.', 'Если партнёр не успевает, система напоминает ему, а при долгом молчании передаёт заявку дальше. Если клиент не отвечает, а попытки задокументированы, это не нарушение.', 'Весь путь виден в карточке клиента: на каком он шаге, кто ждёт действия и сколько осталось времени.'], l: [] },
      { t: '5. Как считаются деньги', p: ['Все доли считаются от всей комиссии застройщика. Её делят три участника. Ваша доля и доля локального партнёра вместе всегда 80%.', 'Деньги начисляются не при депозите. Право на комиссию появляется, когда клиент оплатил первый взнос застройщику. Строка начисления заполняется, когда платформа получила комиссию. До этого строка пустая, и это не ошибка.', 'Реферальная программа Вашу долю не уменьшает: сетевой пул платформа выделяет из своей доли.'], l: ['Платформа: 20%', 'Вы: 40%, 35% или 30% по готовности клиента', 'Локальный партнёр: 40%, 45% или 50% по готовности клиента'] },
      { t: '6. Реферальное дерево', p: ['Если Вы пригласили агента, а он пригласил ещё кого-то, получается дерево до пяти уровней. Когда кто-то в нём закрывает покупку, платформа выделяет из своей доли пул в 5% комиссии застройщика и делит его вверх по дереву, Вам в том числе. Сам агент ничего не теряет.', 'Правила сети не меняются задним числом. Не во всех странах сетевая часть платится одинаково, платформа применяет это сама.'], l: ['уровень 1 (кто пригласил агента): 70% пула', 'уровень 2: 20%', 'уровень 3: 5%', 'уровень 4: 3%', 'уровень 5: 2%'] },
      { t: '7. Что запрещено', p: [], l: ['Приводить клиента, который уже работает с другим агентом или локальным партнёром. Право на клиента решает запись о том, кто привёл его первым.', 'Подавать повторную заявку на того же человека ради второй комиссии: заявки объединяются.', 'Обещать клиенту от имени застройщика цену, скидку, сроки или рассрочку. Условия подтверждает локальный партнёр с платформой.', 'Писать или звонить тому, кто просил прекратить связь или пожаловался. Запрет действует на всех каналах.'] },
      { t: '8. За что закрывают доступ', p: ['Явно названо одно основание, без права восстановления: передача заведомо ложной или вводящей в заблуждение информации о клиенте. Об этом написано в подтверждении при каждой передаче.', 'Остальное складывается из практики, а не из опубликованного списка. Спам-заявки разбираются вручную, это фильтр, а не наказание. Попытка написать тому, кто отказался от связи, фиксируется сразу. Администратор может приостановить или закрыть учётную запись: кабинет покажет это и даст контакт.'], l: [] }];
    const cur = Object.assign({}, SEC[S.sec], { hasList: SEC[S.sec].l.length > 0 });
    const toc = SEC.map((s, i) => ({ t: s.t, on: S.sec === i, pick: () => this.setState({ sec: i }) }));
    const RUL = [['Как устроена программа', 'Housebook платит за две вещи: за клиента, которого Вы привели (личная комиссия), и за партнёров, которых Вы пригласили (сетевая доля). Обе считаются от полученной комиссии по закрытой заявке.'],
      ['Сетевая доля', 'Когда у заявки есть реферальная цепочка, платформа оставляет себе 15% вместо 20%, а 5% образуют сетевой пул. Пул делится по пяти уровням вверх: 70%, 20%, 5%, 3%, 2%.'],
      ['Ваши контакты в сети', 'Телефон, ник в Telegram и почта видны партнёру, который Вас пригласил, чтобы он мог связаться с Вами.'],
      ['Страны', 'Вьетнам, Малайзия и Саудовская Аравия закрыты на всех уровнях. ОАЭ, Оман и Таиланд закрыты на уровнях с третьего по пятый.'],
      ['Активность в сети', 'Раз в 6 месяцев нужно подтвердить активность: одна своя закрытая заявка либо две закрытые заявки у двух разных партнёров первой линии. Считаются заявки, закрытые с 9 сентября 2026. Срок продлевается на 6 месяцев и не сокращается. Напоминания приходят за 60, 30 и 7 дней до конца срока.'],
      ['Отложенный баланс', 'Здесь лежит всё, что удержано по стране или за перерыв в активности. У каждой строки видны причина и дата пересмотра. Доля ждёт выхода 24 месяца, за 30 дней приходит уведомление. Потом строка уходит в спящий режим и не сгорает: деньги Ваши и разблокируются после подтверждения реквизитов и проверки.'],
      ['Выплаты', 'Выплаты собираются партиями по валюте. Нужны реквизиты в профиле, если их нет, платформа попросит их. Если комиссию вернули клиенту, начисленные доли зачитываются против Ваших следующих начислений.']];
    const rules = RUL.map(([t, p]) => ({ t, p, open: !!S.rOpen[t], pick: () => this.setState({ rOpen: Object.assign({}, S.rOpen, { [t]: !S.rOpen[t] }) }) }));
    const SST = ['Чтение', 'Согласие', 'Код', 'Готово'].map((t, i) => ({ t, cls: S.step === i + 1 ? 'step is-cur' : 'step' }));
    return Object.assign(this.baseVals(), { tabs, tCon: S.tab === 'con', tReg: S.tab === 'reg', tRul: S.tab === 'rul', cons, mine, toc, cur, rules,
      prev: () => this.setState({ sec: Math.max(0, S.sec - 1) }), next: () => this.setState({ sec: Math.min(SEC.length - 1, S.sec + 1) }),
      signed: S.signed, notSigned: !S.signed, signOpen: (e) => this.openM('sign', e, { toast: '', step: 1, agree: false, agreeErr: false, code: '', codeErr: false }), m_sign: S.m === 'sign', stepLabel: 'Шаг ' + S.step + ' из 4: ' + ['Чтение', 'Согласие', 'Код', 'Готово'][S.step - 1], s1: S.step === 1, s2: S.step === 2, s3: S.step === 3, s4: S.step === 4,
      toS1: () => this.setState({ step: 1 }), toS2: () => this.setState({ step: 2 }), toS3: () => { if (!S.agree) { this.setState({ agreeErr: true }); return; } this.setState({ step: 3 }); },
      agree: S.agree, toggleAgree: () => this.setState({ agree: !S.agree, agreeErr: false }), agreeErr: S.agreeErr ? 'is-err' : '', agreeMsg: S.agreeErr ? 'Без согласия подписать нельзя' : '',
      code: S.code, setCode: (e) => this.setState({ code: e.target.value.replace(/\D/g, '').slice(0, 6), codeErr: false }), codeErr: S.codeErr ? 'is-err' : '', codeMsg: S.codeErr ? 'Код не подошёл. Проверьте письмо' : '',
      sign: () => { if (S.code !== '123456') { this.setState({ codeErr: true }); return; } this.setState({ step: 4, signed: true }); },
      m_rev: S.m === 'rev', revText: S.rev === 'p1' ? 'Без этого согласия мы не сможем проверить Вашу личность. Передачи клиентов, сетевые начисления и выплаты будут удерживаться, причина будет видна в кабинете.' : 'Мы сразу перестанем связываться с этим клиентом во всех каналах.',
      revOk: (e) => { setSt(S.rev, 'revoked'); this.say('Согласие отозвано', e); } });
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); if (HB.isNovice()) this.state.st = { c1: 'none', c2: 'none', p1: 'none', p2: 'none', p3: 'none', p4: 'none' }; }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o);  return v; }
}; })(Component);
